def edit_distance(a, b):
    """Return the Levenshtein edit distance between strings ``a`` and ``b``.

    The distance is the minimum number of single-character insertions,
    deletions and substitutions required to turn ``a`` into ``b``.

    Edge cases:
      * ``None`` is treated as an empty string.
      * Non-string inputs are coerced with ``str()``.
      * Identical strings give 0; an empty string gives ``len(other)``.
    """
    if a is None:
        a = ""
    if b is None:
        b = ""
    if not isinstance(a, str):
        a = str(a)
    if not isinstance(b, str):
        b = str(b)

    if a == b:
        return 0

    # Keep the shorter string on the DP row to minimize memory.
    if len(a) < len(b):
        a, b = b, a

    if not b:
        return len(a)

    previous = list(range(len(b) + 1))
    for i, ca in enumerate(a, start=1):
        current = [i] + [0] * len(b)
        for j, cb in enumerate(b, start=1):
            if ca == cb:
                current[j] = previous[j - 1]
            else:
                current[j] = 1 + min(
                    previous[j - 1],  # substitution
                    previous[j],      # deletion
                    current[j - 1],   # insertion
                )
        previous = current

    return previous[-1]

def min_coins(coins, amount):
    """Return the minimum number of coins needed to make exactly `amount`,
    or -1 if it cannot be formed. Unlimited supply of each denomination."""
    if amount < 0:
        return -1
    if amount == 0:
        return 0

    coins = [c for c in coins if isinstance(c, int) and c > 0]
    if not coins:
        return -1

    INF = float("inf")
    dp = [INF] * (amount + 1)
    dp[0] = 0

    for value in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= value and dp[value - c] + 1 < best:
                best = dp[value - c] + 1
        dp[value] = best

    return -1 if dp[amount] == INF else dp[amount]

def lcs_length(a, b):
    """Return the length of the longest common subsequence of strings ``a`` and ``b``.

    A subsequence preserves character order but need not be contiguous.
    Empty inputs (or ``None``) yield 0.
    """
    if a is None or b is None:
        return 0
    if not isinstance(a, str) or not isinstance(b, str):
        raise TypeError("lcs_length() arguments must be strings or None")

    # Keep the shorter string on the inner axis to minimize memory.
    if len(a) < len(b):
        a, b = b, a

    if not b:
        return 0

    prev = [0] * (len(b) + 1)
    for i in range(1, len(a) + 1):
        cur = [0] * (len(b) + 1)
        ai = a[i - 1]
        for j in range(1, len(b) + 1):
            if ai == b[j - 1]:
                cur[j] = prev[j - 1] + 1
            else:
                # Best of skipping a[i-1] or skipping b[j-1].
                cur[j] = cur[j - 1] if cur[j - 1] >= prev[j] else prev[j]
        prev = cur

    return prev[len(b)]

def is_sorted(xs):
    """Return True if xs is in non-decreasing order.

    An empty list or a single-element list is considered sorted.
    Equal adjacent elements are allowed (non-decreasing, not strictly increasing).
    """
    if xs is None:
        raise TypeError("is_sorted() expected a sequence, got None")
    # Materialize once so iterables/generators work too.
    items = list(xs)
    for i in range(1, len(items)):
        if items[i] < items[i - 1]:
            return False
    return True

