    return best

def to_base(n, b):
    """Convert integer n to a string in base b (2 <= b <= 16)."""
    if not 2 <= b <= 16:
        raise ValueError("base must be between 2 and 16")
    digits = "0123456789ABCDEF"
    if n == 0:
        return "0"
    sign = "-" if n < 0 else ""
    n = abs(n)
    out = []
    while n:
        n, r = divmod(n, b)
        out.append(digits[r])
    return sign + "".join(reversed(out))

def repeat_with_dash(s, n):
    """Return s repeated n times, joined by single dashes.

    Examples:
        repeat_with_dash("ab", 3) -> "ab-ab-ab"
        repeat_with_dash("ab", 1) -> "ab"
        repeat_with_dash("ab", 0) -> ""
        repeat_with_dash("ab", -5) -> ""
        repeat_with_dash("", 3) -> ""
    """
    if s is None:
        raise TypeError("s must be a string, not None")
    if not isinstance(s, str):
        raise TypeError("s must be a string, got %r" % type(s).__name__)
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an integer, got %r" % type(n).__name__)

    if n <= 0 or s == "":
        return ""
    return "-".join([s] * n)

def two_sum(nums, target):
    """Return [i, j] with i < j and nums[i] + nums[j] == target.

    Among all valid pairs, the one with the smallest i is returned; for that i,
    the smallest j. Returns None if no such pair exists.
    """
    positions = {}
    for idx, value in enumerate(nums):
        positions.setdefault(value, []).append(idx)

    for i, value in enumerate(nums):
        complement = target - value
        for j in positions.get(complement, ()):
            if j > i:
                return [i, j]
    return None

def matrix_multiply(a, b):
    """Multiply matrix a (m x n) by matrix b (n x p), returning the m x p product."""
    if not a or not b:
        return []

    # Determine dimensions
    m = len(a)
    n = len(a[0])
    p = len(b[0])

    # Validate rectangularity and dimensions
    if any(len(row) != n for row in a):
        raise ValueError("Matrix a must be rectangular")
    if any(len(row) != p for row in b):
        raise ValueError("Matrix b must be rectangular")
    if len(b) != n:
        raise ValueError("Number of columns of a must equal number of rows of b")

    result = []
    for i in range(m):
        row = []
        for j in range(p):
            total = 0
            for k in range(n):
                total += a[i][k] * b[k][j]
            row.append(total)
        result.append(row)
    return result

