    else:
        return dp[amount]

def lcs_length(a, b):
    """
    Returns the length of the longest common SUBSEQUENCE of strings a and b.
    Handles edge cases.
    """
    n = len(a)
    m = len(b)

    if n == 0 or m == 0:
        return 0

    if n > m:
        a, b = b, a

    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[n][m]

